INSERT INTO public.quizzes (id, subject, unit, title, description) VALUES ('e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'Citizenship', 'Unit 5', 'Molarum Grade 10 — Citizenship Unit 5: Federalism in Ethiopia', 'Source-grounded Molarum Grade 10 Citizenship questions for Unit 5: Federalism in Ethiopia.') ON CONFLICT (id) DO UPDATE SET subject = EXCLUDED.subject, unit = EXCLUDED.unit, title = EXCLUDED.title, description = EXCLUDED.description;
INSERT INTO public.questions (id, quiz_id, question_type, question_text, correct_answer, explanation, order_index) VALUES ('f1593693-5afc-40dd-8ac0-a4809088d9a3'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'Which sentence best matches the textbook definition of federalism in the excerpt?', 'A political organization dividing government activities between regional governments and a central government so each makes final decisions in some areas', 'The excerpt defines federalism as dividing activities between regional and central governments so that each level has some final decision-making authority, matching the correct option.', 0),('70e55c70-acc1-4be2-87b1-ff8c76cd3360'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'According to the excerpt, what does the principle of devolution in federalism mean?', 'To transfer power to the regional units that constitute the federation', 'The excerpt states devolution means transferring power to the regional units of the federation, making that option correct.', 1),('1470e2c5-45e7-4f5d-8fd6-a59d869c2b5e'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'Which of the following is emphasized about the relationship between federal and regional governments?', 'Neither the federal nor the regional governments are supreme; power is coordinated between them', 'The excerpt explains devolution makes neither federal nor regional governments supreme and power is coordinated, supporting the chosen option.', 2),('b4054206-332f-4410-87b3-a4f1b5f038b2'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'Which element appears in the scholarly definitions of federalism given in the excerpt?', 'A high federal court adjudicates disputes concerning federalism', 'One scholarly definition quoted in the excerpt lists a high federal court adjudicating disputes as a component of federalism, making this option correct.', 3),('9938fb8d-2667-47ef-8e0e-06a85269fad5'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'What lesson about federal and regional governments is illustrated by the Lower Omo Basin flood case study in the excerpt?', 'A coordinated effort of federal and regional governments can help solve problems that exceed regional capacity', 'The case study shows the federal government stepped in when the regional state could not cope and both levels coordinated responses, supporting the chosen answer.', 4),('64c9fa47-92a8-4796-85ad-f4f1fe48579b'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'Which pair names the two types of federalism classified in the excerpt based on how federal laws are executed across the territory?', 'Dual federalism and Cooperative federalism', 'The excerpt classifies federations into Dual federalism and Cooperative federalism based on execution and enforcement across the territory, making that pair correct.', 5),('e1d6ac3f-8924-4d39-8669-9029f4dcb09f'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'Which statement reflects a claimed advantage of dual federalism in the excerpt?', 'It protects local jurisdictions from federal overreach and allows local laws to reflect local needs', 'The excerpt lists as advantages of dual federalism protection from federal overreach and the ability for local laws to reflect local requirements, matching the correct option.', 6),('4d028e64-ac90-4ee5-8f43-bbd1f2ec247b'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'Which is listed in the excerpt as a disadvantage of dual federalism?', 'It leads to tensions and reduced cooperation between federal and state governments', 'The excerpt states dual federalism can keep tensions high and decrease cooperation, which reduces program efficiency, supporting the selected option.', 7),('5aef9c50-654f-458d-8aed-a249151a9820'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'Which metaphor used in the excerpt corresponds to cooperative federalism?', 'Marble-cake federalism', 'The excerpt refers to cooperative federalism as marble-cake federalism to indicate intermingled cooperation across levels, making this option correct.', 8),('ebe5afd0-6807-464c-8740-ee5c94ab68e6'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'Which advantage of cooperative federalism is described in the excerpt?', 'National and state governments work together to provide services efficiently', 'The excerpt lists cooperative federalism advantages including collaborative work between national and state governments to provide services efficiently, matching the correct option.', 9),('4dd0b98f-f7ca-4765-8fe3-09e56d570b7d'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'Which of the following is listed as an essential feature characterizing federations in the excerpt?', 'A written and supreme federal constitution', 'The excerpt identifies a written and supreme federal constitution as an essential feature binding both orders of government, making this the correct choice.', 10),('4053bb57-f92f-4605-8ae7-d5b0d965154c'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'What does the excerpt say about the division of power in federations?', 'Political power is constitutionally divided between the federal government and the states', 'The excerpt explains federations are distinguished by constitutional division of political power between federal and state governments, supporting the answer.', 11),('0b253efb-bcf5-4be2-819f-12d635ddd195'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'According to the excerpt, which statement characterizes a decentralized system of government (not a federation)?', 'Local governments are creations of the center and may be revoked by the center', 'The excerpt contrasts decentralized systems by explaining local governments are creations of the center subject to unilateral withdrawal or revocation, matching the chosen option.', 12),('cd33edce-67e1-4958-837b-d3cd2461f7f8'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'Why does the excerpt say a federation should have a rigid constitution?', 'To protect the spirit of the agreement and prevent the central government from easily curtailing state autonomy', 'The excerpt notes a rigid constitution is regarded as a sacred agreement that should not be easily violated, preventing central curtailment of state autonomy, which supports the answer.', 13),('59b44b18-676d-4f43-8a4b-37ae0b44da85'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'What role does the excerpt assign to a special judiciary in a federation?', 'To adjudicate constitutional disputes and act as custodian of the constitution', 'The excerpt explains a special judiciary is needed to adjudicate constitutional disputes and to declare laws at variance with the constitution invalid, making this option correct.', 14),('2967628a-ddcf-4b69-8e4e-05ab2b95bb7a'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'Which of the following is listed in the excerpt as an advantage of federalism?', 'Increasing citizen participation by providing dual levels of government', 'The excerpt lists increasing citizen participation due to dual levels of government as an advantage, making this option correct.', 15),('6fb42433-bb2f-4ad8-8811-9588c6fa7d62'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'Which disadvantage of federalism is noted in the excerpt?', 'Regional inequalities between states in areas like education funding', 'The excerpt explains federalism can produce regional inequalities—such as differing education spending—so this option is correct.', 16),('9b6336be-44ab-4e7f-82e0-9e17d6f9c74c'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'According to the excerpt, how can federalism undermine patriotism?', 'By promoting strong regionalism that may put one region against another', 'The excerpt notes federalism can promote smaller levels of pride and regionalism that can reduce nationwide patriotism, supporting the selected option.', 17),('b0a06860-1fbd-4678-822c-515970896aff'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'Which feature is presented in the excerpt as peculiar to the Ethiopian federal system?', 'Power division between states and the federal government regulated by the constitution', 'The excerpt describes Ethiopian federalism as having power division between states and the federal government regulated by the constitution, making this option correct.', 18),('72b50214-18b5-4a1b-8f1e-a0cfa9242523'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'multiple_choice', 'Which two federal houses does the Ethiopian constitution provide according to the excerpt?', 'House of People''s Representatives and House of Federation', 'The excerpt states Ethiopia''s constitution provides two federal houses: the House of People''s Representatives and the House of Federation, so the first option is correct.', 19),('a0036493-d61d-453a-803a-88ec3624222e'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'true_false', 'Conflicts are inherent to human behavior and inevitable in day-to-day interactions of human societies.', 'True', 'The unit summary states conflicts have occurred as long as people live in groups and interact, indicating conflicts are inherent and inevitable, so True is correct.', 20),('5b6235f3-39a3-420a-8521-c512dedde13d'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'true_false', 'The statement ''Always peace means the absence of war'' is correct according to the excerpt.', 'False', 'The excerpt and review imply a broader understanding of peace beyond merely absence of war, and the unit review lists this as an item expected to be False, so False is correct.', 21),('eeb33299-a004-470c-8e32-5d3d1563dd33'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'true_false', 'The excerpt implies that in indigenous conflict resolution mechanisms one party necessarily wins and the other loses.', 'False', 'The excerpt describes indigenous mechanisms as restoring peace and harmony and facilitating resolution, not as necessarily producing a winner and loser, so False is correct.', 22),('b33b0ff1-08e7-40bd-8394-b49f9912a722'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'true_false', 'According to the excerpt, indigenous conflict resolution mechanisms provide quick response and reduce regular court load.', 'True', 'The excerpt lists advantages of indigenous mechanisms including quick response and reducing court load, supporting True as the answer.', 23),('88fa834d-f599-4c60-8df0-0cb4fd55e7e4'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'fill_blank', 'Define federalism in one sentence as in the excerpt.', 'Federalism is a system of government where power is divided between federal and regional governments so each level has some final decision-making authority.', 'The excerpt defines federalism as division of power between federal and regional governments with each having final decision-making authority in some areas, which the answer summarizes.', 24),('4f14b32c-962a-4238-8b98-6c58bcb04d72'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'fill_blank', 'Explain briefly what devolution means in the context of federalism according to the excerpt.', 'Devolution means transferring power to the regional units of the federation so neither level is made supreme and power is coordinated between center and regions.', 'The excerpt states devolution transfers power to regions and results in coordination rather than supremacy of either level, which the answer captures.', 25),('f28098da-fd02-4344-8b0a-200356cfc389'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'fill_blank', 'In one sentence, state the key difference between dual federalism and cooperative federalism from the excerpt.', 'Dual federalism clearly divides authority so states and national governments operate separately, while cooperative federalism requires shared power and collaboration on overlapping functions.', 'The excerpt contrasts dual federalism''s clear division of authority with cooperative federalism''s sharing and collaboration on overlapping functions, succinctly summarized in the answer.', 26),('8de26671-8e93-49af-8304-6467f0ef560e'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'fill_blank', 'Why does the excerpt say federations need a written and supreme constitution?', 'Because the terms of the federal bargain and the distribution of powers must be recorded and be supreme so neither order of government derives authority from the other.', 'The excerpt explains a written and supreme constitution records the bargain and provides authority that does not depend on one government deriving power from the other, which the answer explains.', 27),('c745cacc-0ec2-4206-8b27-ae329038e4bb'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'fill_blank', 'Describe in one sentence the role of the special judiciary in a federation as given in the excerpt.', 'The special judiciary adjudicates constitutional disputes and can declare national or local laws invalid if they conflict with the constitution, acting as guardian of the constitution.', 'The excerpt states the special judiciary must adjudicate disputes and has power to declare laws inconsistent with the constitution invalid, matching the answer.', 28),('848b58d8-d191-49e5-862d-d2180c18bb99'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'fill_blank', 'Briefly explain the primary rationale for federalism in contemporary Ethiopia according to the excerpt.', 'The primary rationale is reconciling ethnic diversity with political unity to accommodate the interests of distinct ethnic groups under a federal arrangement.', 'The excerpt states Ethiopia adopted federalism to reconcile ethnic diversity with unity and to accommodate rights and demands of diverse groups, which the answer summarizes.', 29),('a3bc23ca-74ef-4259-8d54-1c01f1ee57ad'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'fill_blank', 'What is the tenure in years of members of the House of Federation as stated in the excerpt?', '5', 'The excerpt states members of the House of Federation are representatives for a tenure of five years, so the numeric answer is 5 years.', 30),('e8cd87ae-a5aa-4f9b-8771-cb00ab4bcc62'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'fill_blank', 'According to the excerpt, how many additional representatives are allocated for each one million additional population of a nationality?', '1', 'The excerpt specifies that for each one million additional population one more representative is allocated, so the numeric answer is 1 representative per one million.', 31),('8e4b230a-fd16-41d5-8557-53a43609abb1'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'fill_blank', 'How many lessons are listed under the ''Lessons'' section in the unit introduction?', '5', 'The unit introduction lists five lessons (meaning, types, key features, advantages/disadvantages, roles), so the count is 5 lessons.', 32),('bd73d92d-56fd-4798-80d6-10b23d98684b'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'fill_blank', 'According to the excerpt''s classification, how many types of federalism are explicitly named under ''Types of federalism'' section?', '2', 'The excerpt explicitly names two types—Dual federalism and Cooperative federalism—so the numeric answer is 2.', 33),('864235fd-2d42-47de-81a3-f10fbf0491f4'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'fill_blank', 'How many numbered advantages of federalism are listed in section 5.4.1 of the excerpt?', '9', 'Section 5.4.1 enumerates nine advantages, numbered 1 through 9, so the numeric answer is 9.', 34),('df6cc9cf-dfb7-43e9-8a5f-d6e8222c7e3f'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'fill_blank', 'How many numbered disadvantages of federalism are listed in section 5.4.2 of the excerpt?', '5', 'Section 5.4.2 lists five disadvantages, numbered 1 to 5, so the numeric answer is 5.', 35),('e5ed22d0-0e28-462f-8de9-05ad3c1f12ba'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'fill_blank', 'How many essential features characterizing federal state structure are summarized at the beginning of section 5.3 in the excerpt?', '3', 'Section 5.3 summarizes three essential features (division of power, decentralized system, written and supreme constitution), so the numeric answer is 3.', 36),('5b987ebf-60dc-41f3-8d69-9c5cce1d0dc4'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'fill_blank', 'How many federal houses does the Ethiopian constitution provide according to the excerpt?', '2', 'The excerpt states the constitution provides two federal houses: the House of People''s Representatives and the House of Federation, so the numeric answer is 2.', 37),('df58f9d2-02bd-4cb6-8b71-1a12b0657b56'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'fill_blank', 'State two powers or functions of the House of People''s Representatives mentioned in the excerpt.', 'It is the highest authority of the federal government and can legislate on federal matters; it may question the prime minister and other federal officials and take measures on executive matters.', 'The excerpt explains the House is the supreme federal organ, legislates on federal jurisdictions, and can question the prime minister and take measures upon request of members, which the answer states.', 38),('aa8e47a3-01db-43dc-8edf-a23bd5f4d2d9'::uuid, 'e3ae16c4-9b1e-4c2c-8eee-b23555c01d34'::uuid, 'fill_blank', 'According to the excerpt, how is representation in the House of Federation determined for nations, nationalities and peoples?', 'Each nationality is represented at least by one member, and for each one million additional population one more representative is allocated; members can be elected directly or indirectly.', 'The excerpt states each nationality has at least one representative, and for each additional one million population one more representative is allocated, with election either directly or indirectly, which the answer summarizes.', 39) ON CONFLICT (id) DO UPDATE SET quiz_id = EXCLUDED.quiz_id, question_type = EXCLUDED.question_type, question_text = EXCLUDED.question_text, correct_answer = EXCLUDED.correct_answer, explanation = EXCLUDED.explanation, order_index = EXCLUDED.order_index;
INSERT INTO public.choices (id, question_id, choice_text, is_correct, order_index) VALUES ('afc5d6d4-30ba-4190-829b-77abd5ffb2dc'::uuid, 'f1593693-5afc-40dd-8ac0-a4809088d9a3'::uuid, 'A political organization dividing government activities between regional governments and a central government so each makes final decisions in some areas', TRUE, 0),('825ad06c-9d94-4495-8ae8-c257ac6caef6'::uuid, 'f1593693-5afc-40dd-8ac0-a4809088d9a3'::uuid, 'A system where the central government is supreme and regional governments have only advisory roles', FALSE, 1),('4e0122fe-da80-4f70-8a14-49105b73bab4'::uuid, 'f1593693-5afc-40dd-8ac0-a4809088d9a3'::uuid, 'An arrangement where regional governments are subordinate and can be revoked at any time by the center', FALSE, 2),('f2914d4d-6f70-486b-8a49-cb8b940ef951'::uuid, 'f1593693-5afc-40dd-8ac0-a4809088d9a3'::uuid, 'A loose association of independent states with no central authority over citizens', FALSE, 3),('5d6733f4-b86c-42e5-8d33-29e5c46b9b6c'::uuid, '70e55c70-acc1-4be2-87b1-ff8c76cd3360'::uuid, 'To transfer power to the regional units that constitute the federation', TRUE, 0),('5e2efd1c-3a83-4349-8c92-4e164a1d4e17'::uuid, '70e55c70-acc1-4be2-87b1-ff8c76cd3360'::uuid, 'To make the federal government fully supreme over regions', FALSE, 1),('76c72d88-a7ce-411c-899e-c0bbaafb9dae'::uuid, '70e55c70-acc1-4be2-87b1-ff8c76cd3360'::uuid, 'To eliminate regional governments and centralize authority', FALSE, 2),('f82b15ba-9659-41ac-8cb6-0c4d94e9e122'::uuid, '70e55c70-acc1-4be2-87b1-ff8c76cd3360'::uuid, 'To allow regions to secede freely from the federation', FALSE, 3),('d929a8e1-f2fa-43ce-892c-2dd2aa49bc91'::uuid, '1470e2c5-45e7-4f5d-8fd6-a59d869c2b5e'::uuid, 'Neither the federal nor the regional governments are supreme; power is coordinated between them', TRUE, 0),('c5975001-33aa-4ca3-8e9c-889b4533d85e'::uuid, '1470e2c5-45e7-4f5d-8fd6-a59d869c2b5e'::uuid, 'The federal government is always superior and can change regional powers unilaterally', FALSE, 1),('09b79e87-6b43-41b7-88d3-49eda39d98b4'::uuid, '1470e2c5-45e7-4f5d-8fd6-a59d869c2b5e'::uuid, 'Regional governments are subordinate creations of the federal government', FALSE, 2),('3888d847-da0d-49ae-87a1-bf0d53c72dc7'::uuid, '1470e2c5-45e7-4f5d-8fd6-a59d869c2b5e'::uuid, 'Regional governments have no direct authority over citizens', FALSE, 3),('4289b760-82a8-492c-8b8d-9259ae6d23fe'::uuid, 'b4054206-332f-4410-87b3-a4f1b5f038b2'::uuid, 'A high federal court adjudicates disputes concerning federalism', TRUE, 0),('01b04e9c-4eb7-4ef7-811d-220f2680d409'::uuid, 'b4054206-332f-4410-87b3-a4f1b5f038b2'::uuid, 'Regional governments are always subordinate to the center', FALSE, 1),('0e67dcdf-333e-4221-84a0-a0d6bd38bc2b'::uuid, 'b4054206-332f-4410-87b3-a4f1b5f038b2'::uuid, 'There is no written constitution in a federation', FALSE, 2),('72feac03-36b5-48a0-85aa-533541c3be1d'::uuid, 'b4054206-332f-4410-87b3-a4f1b5f038b2'::uuid, 'Local governments are creations of the federal government and can be wiped out', FALSE, 3),('b456fc8a-59da-407f-848f-6a74cc8832f4'::uuid, '9938fb8d-2667-47ef-8e0e-06a85269fad5'::uuid, 'A coordinated effort of federal and regional governments can help solve problems that exceed regional capacity', TRUE, 0),('3704c723-ebcc-4f1d-80ab-194c3add2d40'::uuid, '9938fb8d-2667-47ef-8e0e-06a85269fad5'::uuid, 'Regional governments should handle all disasters without federal involvement', FALSE, 1),('04e5a6e5-9dcd-4504-804f-e62de7662e6e'::uuid, '9938fb8d-2667-47ef-8e0e-06a85269fad5'::uuid, 'Federal government always replaces regional efforts in disasters', FALSE, 2),('9e46baee-8479-41dd-82a3-adad6e27f64c'::uuid, '9938fb8d-2667-47ef-8e0e-06a85269fad5'::uuid, 'Only international organizations can effectively respond to large floods', FALSE, 3),('f5b81c3e-07a6-46a9-8b1a-577df457607c'::uuid, '64c9fa47-92a8-4796-85ad-f4f1fe48579b'::uuid, 'Dual federalism and Cooperative federalism', TRUE, 0),('85e46050-9507-491d-8a0d-663a5fde72f3'::uuid, '64c9fa47-92a8-4796-85ad-f4f1fe48579b'::uuid, 'Layer federalism and Centralized federalism', FALSE, 1),('12420733-a1e1-4bc0-85e6-a5beb9c6aea2'::uuid, '64c9fa47-92a8-4796-85ad-f4f1fe48579b'::uuid, 'Unitary federalism and Confederal federalism', FALSE, 2),('f7492df0-5bc0-4ea2-8a6a-29f5022be03e'::uuid, '64c9fa47-92a8-4796-85ad-f4f1fe48579b'::uuid, 'Judicial federalism and Legislative federalism', FALSE, 3),('13ad64b0-3535-45e2-8db9-6239632ec8c8'::uuid, 'e1d6ac3f-8924-4d39-8669-9029f4dcb09f'::uuid, 'It protects local jurisdictions from federal overreach and allows local laws to reflect local needs', TRUE, 0),('456238b7-0df9-46f9-8e07-c161b265f226'::uuid, 'e1d6ac3f-8924-4d39-8669-9029f4dcb09f'::uuid, 'It ensures full cooperation between federal and state governments in all programs', FALSE, 1),('1ab1fc6e-60d9-4e6d-825a-e0086bb44b29'::uuid, 'e1d6ac3f-8924-4d39-8669-9029f4dcb09f'::uuid, 'It centralizes all policymaking to achieve uniformity across states', FALSE, 2),('68ef3d31-9cc7-438e-83f0-af0f60eb7550'::uuid, 'e1d6ac3f-8924-4d39-8669-9029f4dcb09f'::uuid, 'It eliminates tensions between state and federal governments', FALSE, 3),('4eb89317-5017-4862-8a79-8c8a4c51de34'::uuid, '4d028e64-ac90-4ee5-8f43-bbd1f2ec247b'::uuid, 'It leads to tensions and reduced cooperation between federal and state governments', TRUE, 0),('394071de-5bc5-4ded-815b-2b55968742f5'::uuid, '4d028e64-ac90-4ee5-8f43-bbd1f2ec247b'::uuid, 'It guarantees equal policies across all states', FALSE, 1),('2e1fc255-c1b4-4710-8218-186ec47944ad'::uuid, '4d028e64-ac90-4ee5-8f43-bbd1f2ec247b'::uuid, 'It removes state authority entirely', FALSE, 2),('e18285d9-5ac4-48cf-8f51-307facf20a2b'::uuid, '4d028e64-ac90-4ee5-8f43-bbd1f2ec247b'::uuid, 'It prevents any local laws from existing', FALSE, 3),('c2b87be4-5d56-4479-8283-cd6de56db00c'::uuid, '5aef9c50-654f-458d-8aed-a249151a9820'::uuid, 'Marble-cake federalism', TRUE, 0),('78bb629b-c6b9-4d44-82c5-3f2b6382127b'::uuid, '5aef9c50-654f-458d-8aed-a249151a9820'::uuid, 'Layer-cake federalism', FALSE, 1),('